prompts.raw:
function ({ vars }) {
  const system = buildSystemPrompt({
    authorPrompt: AUTHORING_SYSTEM_PROMPT,
    customPrompt: vars.customPrompt,
  });
  return [
    { role: 'system', content: `{% raw %}${system}{% endraw %}` },
    { role: 'user', content: `{% raw %}${vars.request}{% endraw %}` },
  ];
}
